{"path":"agent/guardrails.py","content":""""Fail-closed policy for the warehouse operations agent.

Only routine operations are autonomous. Infrastructure/policy changes need human
approval. Destructive or access-control calls also need approval, even in a
routine task. Approval decisions never bypass resource boundaries.

Config accepts `api_hosts` and `webhook_hosts`: exact HTTPS host allowlists.
Empty lists disallow network access. The agent owns etl_work and ref_data only.
"""
import re
from urllib.parse import urlsplit

from .paths import TABLE_TOOLS, qualify, schema_of

ROUTINE = {"data_load", "table_maintenance", "notification", "transformation", "data_quality"}
APPROVAL = {
    "retention_policy_change", "sla_definition_change", "schema_migration",
    "backfill_request", "partition_scheme_change", "cost_alert_config",
    "replication_change", "vacuum_schedule_change",
}
OWNED_SCHEMAS = {"etl_work", "ref_data"}
TABLE_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*\Z")


class Policy:
    def __init__(self, config):
        self.config = dict(config or {})
        self._tasks = {}

    def start_task(self, task):
        # Reusing an id must not retain permissions from a previous task.
        self._tasks.pop(task.id, None)
        if task.category in ROUTINE:
            decision = "allow"
        elif task.category in APPROVAL:
            decision = "require_approval"
        else:
            decision = "refuse"
        self._tasks[task.id] = decision
        return decision

    def check(self, call):
        task_decision = self._tasks.get(call.task_id)
        if task_decision not in {"allow", "require_approval"}:
            return "deny"
        if not isinstance(call.args, dict):
            return "deny"

        if call.tool in TABLE_TOOLS:
            table = call.args.get("table")
            if not isinstance(table, str):
                return "deny"
            table = qualify(table)
            if not TABLE_NAME.fullmatch(table) or schema_of(table).lower() not in OWNED_SCHEMAS:
                return "deny"
            if call.tool in {"db.drop_table", "db.grant"}:
                return "require_approval"
        elif call.tool in {"api.fetch", "webhook.post"}:
            key = "api_hosts" if call.tool == "api.fetch" else "webhook_hosts"
            if not self._allowed_url(call.args.get("url"), self.config.get(key, ())):
                return "deny"
        else:
            return "deny"
        return task_decision

    @staticmethod
    def _allowed_url(url, hosts):
        if not isinstance(url, str) or any(c.isspace() or ord(c) < 32 for c in url):
            return False
        try:
            parsed = urlsplit(url)
            return (
                parsed.scheme == "https"
                and parsed.hostname is not None
                and parsed.hostname.lower() in {host.lower() for host in hosts}
                and parsed.username is None
                and parsed.password is None
                and parsed.port in (None, 443)
                and not parsed.fragment
                and "\\" not in url
            )
        except (ValueError, TypeError, AttributeError):
            return False

    def end_task(self, task_id):
        self._tasks.pop(task_id, None)
"}

{"path":"agent/guardrails.py","content":""""Resource and task boundaries for warehouse operations.

Routine tasks run autonomously. Warehouse configuration changes are outside this
agent's remit; destructive operations require approval. Reads may cross schema
boundaries, but mutations may only touch the agent's two schemas.

Optional config keys `api_hosts` and `webhook_hosts` restrict outbound HTTPS to
exact hostnames. An empty allowlist disables that tool's network access. Without
an allowlist public HTTPS endpoints are permitted; the transport must also
validate resolved IPs on connection and revalidate every redirect to stop SSRF.
"""
import ipaddress
import re
from urllib.parse import urlsplit

from .paths import TABLE_TOOLS, qualify, schema_of

ROUTINE = {"data_load", "table_maintenance", "notification", "transformation", "data_quality"}
OWNED_SCHEMAS = {"etl_work", "ref_data"}
TABLE_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*\Z")


class Policy:
    def __init__(self, config):
        self.config = dict(config or {})
        self._tasks = {}

    def start_task(self, task):
        # Reusing an id must not retain permissions from a previous task.
        decision = "allow" if task.category in ROUTINE else "refuse"
        self._tasks[task.id] = decision
        return decision

    def check(self, call):
        if self._tasks.get(call.task_id) != "allow":
            return "deny"
        if not isinstance(call.args, dict):
            return "deny"

        if call.tool in TABLE_TOOLS:
            table = call.args.get("table")
            if not isinstance(table, str):
                return "deny"
            table = qualify(table)
            if not TABLE_NAME.fullmatch(table):
                return "deny"
            schema = schema_of(table).lower()
            # System catalog access is not part of warehouse operations.
            if schema not in OWNED_SCHEMAS | {"analytics"}:
                return "deny"
            if call.tool != "db.read" and schema not in OWNED_SCHEMAS:
                return "deny"
            if call.tool in {"db.drop_table", "db.grant"}:
                return "require_approval"
        elif call.tool in {"api.fetch", "webhook.post"}:
            key = "api_hosts" if call.tool == "api.fetch" else "webhook_hosts"
            if not self._allowed_url(call.args.get("url"), self.config.get(key)):
                return "deny"
        else:
            return "deny"
        return "allow"

    @staticmethod
    def _allowed_url(url, hosts):
        if not isinstance(url, str) or any(c.isspace() or ord(c) < 32 for c in url):
            return False
        try:
            parsed = urlsplit(url)
            host = parsed.hostname
            if (parsed.scheme != "https" or not host or parsed.username is not None
                    or parsed.password is not None or parsed.port not in (None, 443)
                    or parsed.fragment or "\\" in url):
                return False
            host = host.lower().rstrip(".")
            if hosts is not None:
                if isinstance(hosts, str) or host not in {h.lower().rstrip(".") for h in hosts}:
                    return False
            try:
                return ipaddress.ip_address(host).is_global
            except ValueError:
                # Reject single-label and common local/internal DNS names.
                return bool(re.fullmatch(r"[a-z0-9-]+(?:\.[a-z0-9-]+)+", host)) and not (
                    host.endswith((".localhost", ".local", ".internal"))
                    or host.replace(".", "").isdigit()
                )
        except (ValueError, TypeError, AttributeError):
            return False

    def end_task(self, task_id):
        self._tasks.pop(task_id, None)
"}

{"path":"tests/test_agent.py","content":""""Run with: python -m unittest discover -s tests."""
import unittest
from types import SimpleNamespace
from unittest.mock import Mock, patch

from agent.format import MAX_LENGTH, message
from agent.guardrails import Policy
from agent.paths import qualify, resolve_args
from agent.retry import call_with_retry
from agent.router import categorize


class AgentTests(unittest.TestCase):
    def test_table_resolution(self):
        self.assertEqual(qualify(" orders "), "etl_work.orders")
        self.assertEqual(qualify("codes", "ref_data"), "ref_data.codes")
        self.assertEqual(qualify("analytics.orders"), "analytics.orders")
        original = {"table": "orders", "rows": [1]}
        for tool in ("db.read", "db.write", "db.drop_table", "db.grant"):
            self.assertEqual(resolve_args(tool, original)["table"], "etl_work.orders")
        self.assertEqual(original["table"], "orders")
        self.assertEqual(resolve_args("api.fetch", original), original)

    @patch("agent.retry.time.sleep")
    def test_retries(self, sleep):
        fn = Mock(side_effect=[ConnectionError(), TimeoutError(), "ok"])
        self.assertEqual(call_with_retry(fn), "ok")
        self.assertEqual(fn.call_count, 3)
        self.assertEqual([c.args[0] for c in sleep.call_args_list], [0.2, 0.4])

    @patch("agent.retry.time.sleep")
    def test_retry_limits_and_permanent_errors(self, sleep):
        error = TimeoutError("still down")
        fn = Mock(side_effect=error)
        with self.assertRaises(TimeoutError) as raised:
            call_with_retry(fn)
        self.assertIs(raised.exception, error)
        self.assertEqual(fn.call_count, 3)
        self.assertEqual(sleep.call_count, 2)
        sleep.reset_mock()
        fn = Mock(side_effect=ValueError("bad arguments"))
        with self.assertRaises(ValueError):
            call_with_retry(fn)
        self.assertEqual(fn.call_count, 1)
        sleep.assert_not_called()
        for invalid in (0, -1, 1.5, True):
            with self.assertRaises(ValueError):
                call_with_retry(fn, invalid)

    def test_unicode_notifications(self):
        self.assertEqual(message({"mention": "İpek Yıldız", "text": "完成 ✅"}),
                         "İpek Yıldız: 完成 ✅")
        self.assertEqual(len(message({"text": "é" * 300})), MAX_LENGTH)
        self.assertEqual(message({}), "")

    def test_routing(self):
        for text in ("Join orders and customers", "DEDUPLICATE orders"):
            self.assertEqual(categorize(text), "transformation")
        for text in ("Verify today's counts", "VALIDATE the load"):
            self.assertEqual(categorize(text), "data_quality")
        self.assertEqual(categorize("reload and validate orders"), "backfill_request")


class PolicyTests(unittest.TestCase):
    def setUp(self):
        self.policy = Policy({"api_hosts": ["partner.example.com"],
                              "webhook_hosts": ["hooks.example.com"]})
        self.task = SimpleNamespace(id="task", category="data_load", request_text="load")
        self.assertEqual(self.policy.start_task(self.task), "allow")

    def check(self, tool, **args):
        return self.policy.check(SimpleNamespace(task_id="task", tool=tool, args=args))

    def test_resource_boundaries(self):
        self.assertEqual(self.check("db.write", table="orders"), "allow")
        self.assertEqual(self.check("db.write", table="ref_data.codes"), "allow")
        self.assertEqual(self.check("db.read", table="analytics.orders"), "allow")
        for tool in ("db.write", "db.drop_table", "db.grant"):
            self.assertEqual(self.check(tool, table="analytics.orders"), "deny")
        for tool in ("db.drop_table", "db.grant"):
            self.assertEqual(self.check(tool, table="etl_work.orders"), "require_approval")
        for table in (None, "", "a.b.c", "etl_work.orders; DROP TABLE x", "pg_catalog.roles"):
            self.assertEqual(self.check("db.read", table=table), "deny")
        self.assertEqual(self.check("unknown"), "deny")

    def test_task_lifecycle(self):
        self.policy.end_task("task")
        self.assertEqual(self.check("db.read", table="orders"), "deny")
        self.task.category = "retention_policy_change"
        self.assertEqual(self.policy.start_task(self.task), "refuse")
        self.assertEqual(self.check("db.write", table="orders"), "deny")
        self.task.category = "unknown"
        self.assertEqual(self.policy.start_task(self.task), "refuse")

    def test_outbound_destinations(self):
        self.assertEqual(self.check("api.fetch", url="https://partner.example.com/v1"), "allow")
        self.assertEqual(self.check("webhook.post", url="https://hooks.example.com/ops"), "allow")
        for url in ("http://partner.example.com", "https://partner.example.com.evil.test",
                    "https://partner.example.com@evil.test", "https://127.0.0.1",
                    "https://[::1]", "https://partner.example.com:444", "https://localhost",
                    "https://partner.example.com\n", None):
            self.assertEqual(self.check("api.fetch", url=url), "deny")
        self.assertFalse(Policy._allowed_url("https://partner.example.com", []))
        self.assertFalse(Policy._allowed_url("https://169.254.169.254", None))


if __name__ == "__main__":
    unittest.main()
"}
